export type Expr =
  | { readonly kind: "literal"; readonly value: bigint }
  | { readonly kind: "add"; readonly left: Expr; readonly right: Expr }
  | { readonly kind: "divide"; readonly numerator: Expr; readonly denominator: Expr }
  | { readonly kind: "negate"; readonly inner: Expr };

export type EvalResult =
  | { readonly kind: "value"; readonly value: bigint }
  | { readonly kind: "division_by_zero" };

export function evaluate(expression: Expr): EvalResult {
  switch (expression.kind) {
    case "literal":
      return { kind: "value", value: expression.value };

    case "add": {
      const left = evaluate(expression.left);
      if (left.kind === "division_by_zero") {
        return left;
      }

      const right = evaluate(expression.right);
      if (right.kind === "division_by_zero") {
        return right;
      }

      return { kind: "value", value: left.value + right.value };
    }

    case "divide": {
      const numerator = evaluate(expression.numerator);
      if (numerator.kind === "division_by_zero") {
        return numerator;
      }

      const denominator = evaluate(expression.denominator);
      if (denominator.kind === "division_by_zero") {
        return denominator;
      }

      if (denominator.value === 0n) {
        return { kind: "division_by_zero" };
      }

      return { kind: "value", value: numerator.value / denominator.value };
    }

    case "negate": {
      const inner = evaluate(expression.inner);
      if (inner.kind === "division_by_zero") {
        return inner;
      }

      return { kind: "value", value: -inner.value };
    }
  }
}

