from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class Literal:
    value: int

@dataclass(frozen=True)
class Add:
    left: Expr
    right: Expr

@dataclass(frozen=True)
class Divide:
    numerator: Expr
    denominator: Expr

@dataclass(frozen=True)
class Negate:
    inner: Expr

type Expr = Literal | Add | Divide | Negate

@dataclass(frozen=True)
class ValueResult:
    value: int

@dataclass(frozen=True)
class DivisionByZero:
    pass

type EvalResult = ValueResult | DivisionByZero


def _truncate_toward_zero(numerator: int, denominator: int) -> int:
    quotient: int = abs(numerator) // abs(denominator)
    if (numerator < 0) != (denominator < 0):
        return -quotient
    return quotient


def evaluate(expression: Expr) -> EvalResult:
    if isinstance(expression, Literal):
        return ValueResult(expression.value)

    if isinstance(expression, Add):
        left: EvalResult = evaluate(expression.left)
        if isinstance(left, DivisionByZero):
            return left

        right: EvalResult = evaluate(expression.right)
        if isinstance(right, DivisionByZero):
            return right

        return ValueResult(left.value + right.value)

    if isinstance(expression, Divide):
        numerator: EvalResult = evaluate(expression.numerator)
        if isinstance(numerator, DivisionByZero):
            return numerator

        denominator: EvalResult = evaluate(expression.denominator)
        if isinstance(denominator, DivisionByZero):
            return denominator

        if denominator.value == 0:
            return DivisionByZero()

        return ValueResult(
            _truncate_toward_zero(numerator.value, denominator.value)
        )

    inner: EvalResult = evaluate(expression.inner)
    if isinstance(inner, DivisionByZero):
        return inner

    return ValueResult(-inner.value)

